from collections import Counter

# Test the hypothesis: copy the top non-background part vertically down
# Copy starts at the position of the special color (5 in demo input at row 7, col 6)

def copy_pattern_down(grid, special_color, shift_row, shift_col):
    """Copy all non-background non-special cells, shifted down by shift_row and right by shift_col"""
    h, w = len(grid), len(grid[0])
    new_grid = [row[:] for row in grid]

    # Find min row of non-background
    min_row = min(r for r, row in enumerate(grid) for c, val in enumerate(row) if val != 0)

    # For each non-background non-special cell, copy to new position
    for r in range(min_row, h):
        for c in range(w):
            if grid[r][c] != 0 and grid[r][c] != special_color:
                new_r = r + shift_row
                new_c = c + shift_col
                if 0 <= new_r < h and 0 <= new_c < w:
                    new_grid[new_r][new_c] = grid[r][c]

    return new_grid

